              ) : filteredPublications.length === 0 ? (
                <p>
                  Aucune publication trouvée correspondant aux domaines de votre
                  entreprise.
                </p>
              ) : (
                <div className="table-responsive">
                  <table className="table table-hover">
                    <thead>
                      <tr>
                        <th>Date de publication</th>
                        <th>Titre</th>
                        <th>Type de publication</th>
                        <th>Numéro</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filteredPublications.map((pub) => (
                        <tr key={pub.id} style={{ cursor: "pointer" }}>
                          <td>
                            <div className="d-none d-md-block">
                              {pub.date_publication}
                            </div>
                            <div className="d-md-none small">
                              {pub.date_publication}
                            </div>
                          </td>
                          <td>
                            <div className="fw-bold">{pub.titre}</div>
                          </td>
                          <td>{pub.type_publication}</td>
                          <td>{pub.numero}</td>
                          <td>
                            <button
                              type="button"
                              className="btn btn-sm btn-outline-primary"
                              onClick={() => {
                                setSelectedDocument(pub.full_data);
                                setShowModal(true);
                              }}
                            >
                              Voir
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>

          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Bibliothèque de documents</h5>
            </div>
            <div className="card-body">
              <div className="mb-3">
                <input
                  type="text"
                  className="form-control"
                  placeholder="Rechercher par mot-clé..."
                />
              </div>
              <div className="row">
                {[1, 2, 3, 4].map((i) => (
                  <div key={i} className="col-lg-3 col-md-4 col-sm-6 mb-3">
                    <div className="card document-card">
                      <div className="card-body text-center">
                        <svg
                          width="48"
                          height="48"
                          fill="currentColor"
                          className="text-danger mb-2"
                          viewBox="0 0 16 16"
                        >
                          <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5L14 4.5zM9.5 3A1.5 1.5 0 0 0 11 4.5h2V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1h5.5v2z" />
                        </svg>
                        <h6 className="card-title">Document {i}</h6>
                        <small className="text-muted">PDF - 2.3 MB</small>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );

  const renderAlertes = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Alertes & Résultats</h2>
        <p className="text-muted">
          Suivi des notifications et résultats de candidatures
        </p>
      </div>

      {loadingActiveCompany ? (
        <p>Chargement des données de l'entreprise...</p>
      ) : errorActiveCompany ? (
        <div className="alert alert-danger">
          Erreur lors du chargement de l'entreprise :{" "}
          {errorActiveCompany.message}. Veuillez recharger la page.
        </div>
      ) : !activeCompany ? (
        <div className="alert alert-info">
          Veuillez créer votre entreprise pour accéder à vos alertes et
          résultats.
        </div>
      ) : (
        <div className="row">
          <div className="col-lg-8 mb-4">
            <div className="card">
              <div className="card-header">
                <h5 className="mb-0">
                  Alertes non traitées (pour {activeCompany.nom})
                </h5>
              </div>
              <div className="card-body">
                {loadingAlertes ? (
                  <p>Chargement des alertes...</p>
                ) : errorAlertes ? (
                  <div className="alert alert-danger">
                    Erreur lors du chargement des alertes :{" "}
                    {errorAlertes.message}
                  </div>
                ) : alertesApi.length === 0 ? (
                  <p>Aucune alerte trouvée pour votre entreprise.</p>
                ) : (
                  alertesApi.map((alerte) => (
                    <div
                      key={alerte.id}
                      className="d-flex flex-column flex-sm-row justify-content-between align-items-start align-items-sm-center border-bottom py-2"
                    >
                      <div className="mb-2 mb-sm-0">
                        <h6 className="mb-1">
                          {alerte.type_alerte}: {alerte.contenu_alerte}
                        </h6>
                        <small className="text-muted">
                          {new Date(alerte.date_alerte).toLocaleDateString(
                            "fr-FR"
                          )}{" "}
                          - Canal: {alerte.canal_alerte}
                        </small>
                        {alerte.publication && (
                          <small className="text-muted d-block mt-1">
                            Publication: {alerte.publication.titre}
                          </small>
                        )}
                        {alerte.entreprise && (
                          <small className="text-muted d-block">
                            Entreprise: {alerte.entreprise.nom}
                          </small>
                        )}
                      </div>
                      <div className="d-flex">
                        <button className="btn btn-sm btn-outline-success me-2">
                          <svg
                            width="16"
                            height="16"
                            fill="currentColor"
                            viewBox="0 0 16 16"
                          >
                            <path d="M10.97 4.97a.75.75 0 0 1 1.07 1.05l-3.99 4.99a.75.75 0 0 1-1.08.02L4.324 8.384a.75.75 0 1 1 1.06-1.06l2.094 2.093 3.473-4.425a.267.267 0 0 1 .02-.022z" />
                          </svg>
                        </button>
                        <button className="btn btn-sm btn-outline-danger">
                          <svg
                            width="16"
                            height="16"
                            fill="currentColor"
                            viewBox="0 0 16 16"
                          >
                            <path d="M4.646 4.646a.5.5 0 0 1 .708 0L8 7.293l2.646-2.647a.5.5 0 0 1 .708.708L8.707 8l2.647 2.646a.5.5 0 0 1-.708.708L8 8.707l-2.646 2.647a.5.5 0 0 1-.708-.708L7.293 8 4.646 5.354a.5.5 0 0 1 0-.708z" />
                          </svg>
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>

          <div className="col-lg-4">
            <div className="card">
              <div className="card-header">
                <h5 className="mb-0">
                  Résultats récents (pour {activeCompany.nom})
                </h5>
              </div>
              <div className="card-body">
                {loadingResultats ? (
                  <p>Chargement des résultats...</p>
                ) : errorResultats ? (
                  <div className="alert alert-danger">
                    Erreur lors du chargement des résultats :{" "}
                    {errorResultats.message}
                  </div>
                ) : resultatsApi.length === 0 ? (
                  <p>Aucun résultat trouvé pour votre entreprise.</p>
                ) : (
                  resultatsApi.map((resultat) => (
                    <div key={resultat.marche.id} className="mb-3">
                      <div className="d-flex justify-content-between align-items-center mb-1">
                        <span className="fw-bold">
                          {resultat.marche.publication.titre}
                        </span>
                        <span
                          className={`badge ${
                            resultat.entreprise_attributaire &&
                            resultat.entreprise_attributaire.id ===
                              activeCompany.id
                              ? "bg-success"
                              : "bg-danger"
                          }`}
                        >
                          {resultat.entreprise_attributaire &&
                          resultat.entreprise_attributaire.id ===
                            activeCompany.id
                            ? "Retenu"
                            : "Non retenu"}
                        </span>
                      </div>
                      <small className="text-muted d-block">
                        Résultat publié le{" "}
                        {new Date(resultat.date_attribution).toLocaleDateString(
                          "fr-FR"
                        )}
                      </small>
                      <small className="text-muted d-block">
                        Attributaire:{" "}
                        {resultat.entreprise_attributaire
                          ? resultat.entreprise_attributaire.nom
                          : "N/A"}
                      </small>
                      <small className="text-muted d-block">
                        Montant attribué: {resultat.montant_attribue}
                      </small>
                      <a
                        href={resultat.marche.publication.source}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="small"
                      >
                        Voir l'annonce officielle
                      </a>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );

  const renderProfil = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Profil</h2>
        <p className="text-muted">Gestion des informations de l'entreprise</p>
      </div>

      {loadingActiveCompany ? (
        <p>Chargement du profil de l'entreprise...</p>
      ) : errorActiveCompany ? (
        <div className="alert alert-danger">
          Erreur lors du chargement du profil : {errorActiveCompany.message}.
          Veuillez recharger la page.
        </div>
      ) : !activeCompany ? (
        <div className="alert alert-info">
          Veuillez créer votre entreprise pour gérer votre profil.
        </div>
      ) : (
        <div className="row">
          <div className="col-lg-8 mb-4">
            <div className="card mb-4">
              <div className="card-header">
                <h5 className="mb-0">Informations de l'entreprise</h5>
              </div>
              <div className="card-body">
                <form onSubmit={handleSubmitUpdateProfile}>
                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <label className="form-label">Nom de l'entreprise</label>
                      <input
                        type="text"
                        className="form-control"
                        value={profileData.nom || ""}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            nom: e.target.value,
                          })
                        }
                      />
                    </div>
                    <div className="col-md-6 mb-3">
                      <label className="form-label">
                        Numéro d'identification
                      </label>
                      <input
                        type="text"
                        className="form-control"
                        value={profileData.numeroIdentification || ""}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            numeroIdentification: e.target.value,
                          })
                        }
                      />
                    </div>
                  </div>
                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <label className="form-label">SIRET</label>
                      <input
                        type="text"
                        className="form-control"
                        value={profileData.siret || ""}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            siret: e.target.value,
                          })
                        }
                      />
                    </div>
                    <div className="col-md-6 mb-3">
                      <label className="form-label">Nom du représentant</label>
                      <input
                        type="text"
                        className="form-control"
                        value={profileData.nomRepresentant || ""}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            nomRepresentant: e.target.value,
                          })
                        }
                      />
                    </div>
                  </div>
                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <label className="form-label">
                        Prénom du représentant
                      </label>
                      <input
                        type="text"
                        className="form-control"
                        value={profileData.prenomRepresentant || ""}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            prenomRepresentant: e.target.value,
                          })
                        }
                      />
                    </div>
                    <div className="col-md-6 mb-3">
                      <label className="form-label">Adresse</label>
                      <input
                        type="text"
                        className="form-control"
                        value={profileData.adresse || ""}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            adresse: e.target.value,
                          })
                        }
                      />
                    </div>
                  </div>
                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <label className="form-label">Email</label>
                      <input
                        type="email"
                        className="form-control"
                        value={profileData.email || ""}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            email: e.target.value,
                          })
                        }
                      />
                    </div>
                    <div className="col-md-6 mb-3">
                      <label className="form-label">Téléphone</label>
                      <input
                        type="tel"
                        className="form-control"
                        value={profileData.telephone || ""}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            telephone: e.target.value,
                          })
                        }
                      />
                    </div>
                  </div>

                  {/* Secteur d'activité */}
                  <div className="mb-3">
                    <label className="form-label">Secteur d'activité</label>
                    {loadingSecteurs ? (
                      <p>Chargement des secteurs...</p>
                    ) : errorSecteurs ? (
                      <p className="text-danger">
                        Erreur de chargement des secteurs:{" "}
                        {errorSecteurs.message}
                      </p>
                    ) : (
                      <select
                        className="form-select"
                        value={
                          profileData.secteurActivite
                            ? profileData.secteurActivite.id
                            : ""
                        }
                        onChange={handleProfileSecteurChange}
                      >
                        <option value="">Sélectionner un secteur</option>
                        {apiSecteursActivite.map((secteur) => (
                          <option key={secteur.id} value={secteur.id}>
                            {secteur.nom}
                          </option>
                        ))}
                      </select>
                    )}
                  </div>

                  {/* Domaines d'activité */}
                  <div className="mb-3">
                    <label className="form-label">Domaines d'activité</label>
                    {loadingDomaines ? (
                      <p>Chargement des domaines...</p>
                    ) : errorDomaines ? (
                      <p className="text-danger">
                        Erreur de chargement des domaines:{" "}
                        {errorDomaines.message}
                      </p>
                    ) : (
                      <div className="row">
                        {apiDomainesActivite.map((domaine) => (
                          <div key={domaine.id} className="col-md-6 mb-2">
                            <div className="form-check">
                              <input
                                className="form-check-input"
                                type="checkbox"
                                id={`domaine-${domaine.id}`}
                                checked={profileData.domainesActivite.some(
                                  (d) => d.id === domaine.id
                                )}
                                onChange={() =>
                                  handleProfileDomaineChange(domaine.id)
                                }
                              />
                              <label
                                className="form-check-label"
                                htmlFor={`domaine-${domaine.id}`}
                              >
                                {domaine.libelle}
                              </label>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  <button
                    type="submit"
                    className="btn btn-cta"
                    disabled={loadingProfileUpdate}
                  >
                    {loadingProfileUpdate
                      ? "Enregistrement..."
                      : "Enregistrer les modifications"}
                  </button>
                  {errorProfileUpdate && (
                    <p className="text-danger mt-2">
                      Erreur: {errorProfileUpdate.message}
                    </p>
                  )}
                </form>
              </div>
            </div>

            {/* Section Ajout de Secteur */}
            <div className="card mb-4">
              <div className="card-header">
                <h5 className="mb-0">Ajouter un nouveau secteur</h5>
              </div>
              <div className="card-body">
                <form onSubmit={handleAddSecteur}>
                  <div className="mb-3">
                    <label className="form-label">Nom du secteur</label>
                    <input
                      type="text"
                      className="form-control"
                      value={newSecteurNom}
                      onChange={(e) => setNewSecteurNom(e.target.value)}
                      required
                    />
                  </div>
                  <button type="submit" className="btn btn-cta">
                    Ajouter le secteur
                  </button>
                </form>
              </div>
            </div>

            {/* Section Ajout de Domaine */}
            <div className="card mb-4">
              <div className="card-header">
                <h5 className="mb-0">Ajouter un nouveau domaine</h5>
              </div>
              <div className="card-body">
                <form onSubmit={handleAddDomaine}>
                  <div className="mb-3">
                    <label className="form-label">Libellé du domaine</label>
                    <input
                      type="text"
                      className="form-control"
                      value={newDomaineLibelle}
                      onChange={(e) => setNewDomaineLibelle(e.target.value)}
                      required
                    />
                  </div>
                  <button type="submit" className="btn btn-cta">
                    Ajouter le domaine
                  </button>
                </form>
              </div>
            </div>
          </div>

          <div className="col-lg-4">
            <div className="card">
              <div className="card-header">
                <h5 className="mb-0">Changer le mot de passe</h5>
              </div>
              <div className="card-body">
                <form onSubmit={handleSubmitChangePassword}>
                  <div className="mb-3">
                    <label className="form-label">Mot de passe actuel</label>
                    <input
                      type="password"
                      className="form-control"
                      value={currentPassword}
                      onChange={(e) => setCurrentPassword(e.target.value)}
                      required
                    />
                  </div>
                  <div className="mb-3">
                    <label className="form-label">Nouveau mot de passe</label>
                    <input
                      type="password"
                      className="form-control"
                      value={newPassword}
                      onChange={(e) => setNewPassword(e.target.value)}
                      required
                    />
                  </div>
                  <div className="mb-3">
                    <label className="form-label">
                      Confirmer le nouveau mot de passe
                    </label>
                    <input
                      type="password"
                      className="form-control"
                      value={confirmNewPassword}
                      onChange={(e) => setConfirmNewPassword(e.target.value)}
                      required
                    />
                  </div>
                  <button
                    type="submit"
                    className="btn btn-cta w-100"
                    disabled={loadingPasswordUpdate}
                  >
                    {loadingPasswordUpdate
                      ? "Mise à jour..."
                      : "Mettre à jour le mot de passe"}
                  </button>
                  {errorPasswordUpdate && (
                    <p className="text-danger mt-2">
                      Erreur: {errorPasswordUpdate.message}
                    </p>
                  )}
                </form>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );

  const renderAddEntrepriseModal = () => (
    <div
      className={`modal fade ${showAddEntrepriseModal ? "show" : ""}`}
      style={{ display: showAddEntrepriseModal ? "block" : "none" }}
      tabIndex="-1"
      onClick={() => setShowAddEntrepriseModal(false)}
    >
      <div className="modal-dialog modal-lg">
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <div className="modal-header">
            <h5 className="modal-title">Créer votre entreprise</h5>
          </div>
          <form onSubmit={handleSubmitAddEntreprise}>
            <div className="modal-body">
              <p className="text-muted">
                Veuillez renseigner les informations de votre entreprise pour
                commencer.
              </p>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Nom de l'entreprise *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.nom}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        nom: e.target.value,
                      })
                    }
                    required
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">
                    Numéro d'identification *
                  </label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.numeroIdentification}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        numeroIdentification: e.target.value,
                      })
                    }
                    required
                  />
                </div>
              </div>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">SIRET *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.siret}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        siret: e.target.value,
                      })
                    }
                    required
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">Téléphone</label>
                  <input
                    type="tel"
                    className="form-control"
                    value={addEntrepriseData.telephone}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        telephone: e.target.value,
                      })
